fn copy(arr: &Vec<i8>) -> Vec<i8> {
    // Create a new vector to hold the copied elements
    let mut result = Vec::with_capacity(arr.len());
    
    // Iterate over the input vector and copy each element to the result vector
    for &item in arr.iter() {
        result.push(item);
    }
    
    // Return the result vector
    result
}